function idbPut(js){return idb().then(db=>new Promise((res,rej)=>{const t=db.transaction(IDBS,"readwrite");t.objectStore(IDBS).put(js,"data");t.oncomplete=()=>{db.close();res()};t.onerror=t.onabort=()=>{db.close();rej(t.error)}}))}
